using Homestay.GUI.Common;
using Homestay.GUI.Infrastructure;
using Homestay.DTO.Finance;
using Homestay.DTO.Enums;
using Homestay.GUI.Staff;

namespace Homestay.GUI.Accountant;

public partial class FrmSettlementDetail : ScreenForm
{
    private readonly AsyncLoader loader=new(); private AppServices? services;private int id;private SettlementDraftResult? current;
    public FrmSettlementDetail()
    {
        InitializeComponent();
        HelpText = "Không gửi khi còn đơn chưa chốt. Trạng thái: Nháp → Đã gửi → Đã trả; khi gửi nhầm có thể mở lại với lý do.";Disposed+=(_,_)=>loader.Dispose();
    }
    public FrmSettlementDetail(AppServices services,int id):this(){this.services=services;this.id=id;EmployeeUi.Activate(pendingNotice,sendButton,reopenButton,feedbackButton,payButton,printButton);var canWrite=services.Session?.Position==Homestay.DTO.Enums.Position.Accountant;sendButton.Enabled=reopenButton.Enabled=feedbackButton.Enabled=payButton.Enabled=canWrite;grid0.SetColumns("Mã đơn","Ngày trả","Loại","Tiền phòng","Đã thu","Hoàn","Giữ lại","Hoa hồng","Giảm giá","Trả chủ");grid1.SetColumns("Mã đơn","Trạng thái","Vấn đề");grid2.SetColumns("Thời điểm","Phản hồi");grid3.SetColumns("Thời điểm","Hành động","Người","Lý do");sendButton.Click+=async(_,_)=>await SendAsync();reopenButton.Click+=async(_,_)=>await ReopenAsync();feedbackButton.Click+=async(_,_)=>await FeedbackAsync();payButton.Click+=async(_,_)=>await PayAsync();printButton.Click+=(_,_)=>Print();Shown+=async(_,_)=>await ReloadAsync();}
    public async Task RefreshFromServerAsync()=>await ReloadAsync();
    private async Task ReloadAsync(){if(services is null)return;try{await loader.LoadAsync(ct=>services.Settlements.GetAsync(id,ct),d=>{current=d;filterPanelField0.Text=$"{d.Year}/{d.Month:00} · Kỳ {d.PeriodNo} · #{d.Id}";filterPanelField1.Text=$"{d.HomestayName} · Chủ: {d.OwnerName} · {d.OwnerBankName} {d.OwnerBankAccountNo} ({d.OwnerBankAccountName})";filterPanelField2.Text=UiFormat.Money(d.Totals.PayoutAmount);filterPanelField3.Text=d.Status.ToString();var items=d.Items;var table=new System.Data.DataTable();for(var i=0;i<10;i++)table.Columns.Add("Column"+i,typeof(object));foreach(var x in items)table.Rows.Add(x.BookingCode,x.CheckOut.ToString("dd/MM/yyyy",UiFormat.Vietnamese),x.ItemType,UiFormat.Money(x.RoomAmount),UiFormat.Money(x.DepositAmount),UiFormat.Money(x.RefundAmount),UiFormat.Money(x.RetainedAmount),UiFormat.Money(x.CommissionAmount),UiFormat.Money(x.DiscountAmount),UiFormat.Money(x.PayoutAmount));grid0.SetPage(table,items.Count,1);var pending=new System.Data.DataTable();pending.Columns.Add("Column0",typeof(object));pending.Columns.Add("Column1",typeof(object));pending.Columns.Add("Column2",typeof(object));foreach(var code in d.UnfinalizedBookingCodes)pending.Rows.Add(code,"Chưa chốt","Cần xử lý trước khi gửi");grid1.SetPage(pending,d.UnfinalizedBookingCodes.Count,1);var fb=new System.Data.DataTable();fb.Columns.Add("Column0",typeof(object));fb.Columns.Add("Column1",typeof(object));if(!string.IsNullOrWhiteSpace(d.OwnerFeedback))fb.Rows.Add("Phản hồi",d.OwnerFeedback);grid2.SetPage(fb,fb.Rows.Count,1);var history=new System.Data.DataTable();for(var i=0;i<4;i++)history.Columns.Add("Column"+i,typeof(object));foreach(var h in d.History)history.Rows.Add(UiFormat.VietnamTime(new DateTimeOffset(DateTime.SpecifyKind(h.AtUtc,DateTimeKind.Utc))).ToString("dd/MM/yyyy HH:mm"),h.Action,h.ActorName,h.Note);grid3.SetPage(history,d.History.Count,1);var canWrite=services.Session?.Position==Homestay.DTO.Enums.Position.Accountant;sendButton.Enabled=canWrite&&d.Status==SettlementStatus.Draft;reopenButton.Enabled=canWrite&&d.Status==SettlementStatus.Sent;payButton.Enabled=canWrite&&d.Status==SettlementStatus.Sent;feedbackButton.Enabled=canWrite&&d.Status!=SettlementStatus.Draft;printButton.Enabled=true;pendingNotice.Text=d.UnfinalizedBookingCodes.Count==0?"Dữ liệu quyết toán đã tải.":"Chưa thể gửi: còn đơn chưa chốt "+string.Join(", ",d.UnfinalizedBookingCodes);});}catch(Exception e){if(!IsDisposed)ErrorHandler.Show(e,this);}}
    private async Task SendAsync(){if(current is null)return;try{if(MessageBox.Show(this,"Gửi bảng đối soát cho chủ?","Xác nhận",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;await services!.Settlements.SendAsync(new(id,current.RowVer,""));await ReloadAsync();}catch(Exception e){ErrorHandler.Show(e,this);}}
    private async Task ReopenAsync(){if(current is null)return;using var d=new FieldsDialog("Mở lại đối soát",new FieldSpec("reason","Lý do",FieldKind.Multiline,Required:true,MaxLength:500));if(d.ShowDialog(this)!=DialogResult.OK)return;try{await services!.Settlements.ReopenAsync(new(id,current.RowVer,(string)d.Values["reason"]!));await ReloadAsync();}catch(Exception e){ErrorHandler.Show(e,this);}}
    private async Task FeedbackAsync(){if(current is null)return;using var d=new FieldsDialog("Ghi phản hồi của chủ",new FieldSpec("feedback","Phản hồi",FieldKind.Multiline,Required:true,MaxLength:500));if(d.ShowDialog(this)!=DialogResult.OK)return;try{await services!.Settlements.RecordOwnerFeedbackAsync(new(id,current.RowVer,(string)d.Values["feedback"]!));await ReloadAsync();}catch(Exception e){ErrorHandler.Show(e,this);}}
    private async Task PayAsync(){if(current is null)return;using var d=new FieldsDialog("Ghi đã trả chủ",new FieldSpec("reference","Mã giao dịch",FieldKind.Text,Required:current.Totals.PayoutAmount>0,MaxLength:100));if(d.ShowDialog(this)!=DialogResult.OK)return;try{await services!.Settlements.MarkPaidAsync(new(id,current.RowVer,Convert.ToString(d.Values["reference"])));await ReloadAsync();}catch(Exception e){ErrorHandler.Show(e,this);}}
    private void Print(){if(current is null)return;var content=new PrintContent("BẢNG ĐỐI SOÁT CHỦ HOMESTAY",[$"Homestay: {current.HomestayName} · Chủ: {current.OwnerName} · Kỳ {current.Year}/{current.Month:00}/{current.PeriodNo}",$"Trạng thái: {current.Status}",$"Tổng tiền giữ: {UiFormat.Money(current.Totals.TotalRetained)} · Hoa hồng: {UiFormat.Money(current.Totals.TotalCommission)}",$"Số tiền chuyển chủ: {UiFormat.Money(current.Totals.PayoutAmount)} ({Homestay.BLL.Rules.VietnameseAmountWords.Spell(current.Totals.PayoutAmount)})"],["Mã đơn","Tiền giữ","Hoa hồng","Giảm giá","Trả chủ"],current.Items.Select(x=>new[]{x.BookingCode,UiFormat.Money(x.RetainedAmount),UiFormat.Money(x.CommissionAmount),UiFormat.Money(x.DiscountAmount),UiFormat.Money(x.PayoutAmount)}).ToArray(),"In bởi Fuji Homestay");DocumentPrinter.Preview(this,content);}
}
